update pages set contenu = '{"gabarit":"fiche","chapeau":"ALSTEF Group, spécialiste mondial des solutions d''automatisation logistique, a choisi Migen pour renforcer ses équipes de terrain. Plusieurs intervenants ont été déployés sur le contrôle de chantier de projets stratégiques.","fiche":[],"contexte":"**Un pic d''activité chantier arrive toujours au mauvais moment.** Soit vous recrutez dans l''urgence, soit vous videz vos équipes internes. Les deux coûtent cher.\nALSTEF Group gère des chantiers complexes, avec des systèmes automatisés, dans des environnements exigeants :\n**Le contrôle de chantier est une phase clé** pour la conformité, la sécurité et la qualité des installations livrées.\n**Des techniciens capables de s''intégrer vite** étaient nécessaires sur les projets stratégiques.\n**Un renfort fiable manquait** pour le suivi des prestataires et la vérification des installations.\n**La souplesse comptait autant que la compétence** : le besoin suit les pics d''activité chantier.","intervention":"**Des techniciens dans l''équipe projet** : Un ou plusieurs intervenants assurent le suivi opérationnel de chantier au sein des équipes ALSTEF Group.\n**Des profils autonomes** : Intervenants expérimentés, qui comprennent les environnements industriels automatisés sans période de découverte.\n**Une prestation encadrée** : Les équipes Migen coordonnent la mission pendant toute sa durée.\n**Une durée ajustable** : La mission va de quelques semaines à plusieurs mois, selon la charge chantier.\n**Un cadre contractuel simple** : Sans avenant, sans rupture de charge, avec un tarif horaire maîtrisé.","resultats":[]}'::jsonb where path = '/preuves/alstef-group/';
update pages set contenu = jsonb_set(contenu, '{fiche}', (contenu->'fiche') || '[{"libelle":"Client","valeur":"ALSTEF Group, automatisation logistique"},{"libelle":"Période","valeur":"2025 à 2026"},{"libelle":"Nature des travaux","valeur":"Contrôle et suivi de chantier"},{"libelle":"Périmètre","valeur":"Suivi des prestataires, vérification des installations, respect des procédures"},{"libelle":"Environnements","valeur":"Aéroports, logistique, industrie"},{"libelle":"Durée de mission","valeur":"De quelques semaines à plusieurs mois"},{"libelle":"Cadre","valeur":"Sans avenant, tarif horaire maîtrisé"}]'::jsonb) where path = '/preuves/alstef-group/';
update pages set contenu = jsonb_set(contenu, '{resultats}', (contenu->'resultats') || '[{"valeur":"Les phases critiques sécurisées","libelle":"Le contrôle de chantier a été tenu sur les projets stratégiques."},{"valeur":"Le niveau de qualité maintenu","libelle":"La qualité et la conformité des installations livrées sont restées au niveau attendu."},{"valeur":"Aucun recrutement d''urgence","libelle":"ALSTEF Group a absorbé la charge projet sans recruter dans la précipitation et sans déplacer ses ressources internes d''un site à l''autre."}]'::jsonb) where path = '/preuves/alstef-group/';
